package com.ridex.location.exception;
import jakarta.servlet.http.HttpServletRequest; import org.junit.jupiter.api.Test; import org.springframework.mock.web.MockHttpServletRequest; import org.springframework.http.HttpStatus; import static org.junit.jupiter.api.Assertions.*;
class GlobalExceptionHandlerTest { GlobalExceptionHandler handler=new GlobalExceptionHandler(); MockHttpServletRequest request(){var r=new MockHttpServletRequest();r.setRequestURI("/api/v1/location/drivers/me");r.addHeader("X-Correlation-Id","corr-123");return r;} @Test void resourceNotFoundMaps404(){var response=handler.handleResourceNotFound(new ResourceNotFoundException("missing"),request());assertEquals(HttpStatus.NOT_FOUND,response.getStatusCode());assertEquals("RESOURCE_NOT_FOUND",response.getBody().code());assertEquals("corr-123",response.getBody().correlationId());} @Test void invalidCredentialsMaps401(){var response=handler.handleInvalidCredentials(new InvalidCredentialsException("bad"),request());assertEquals(HttpStatus.UNAUTHORIZED,response.getStatusCode());assertEquals("INVALID_CREDENTIALS",response.getBody().code());} @Test void illegalOperationMaps403(){var response=handler.handleIllegalOperation(new IllegalOperationException("denied"),request());assertEquals(HttpStatus.FORBIDDEN,response.getStatusCode());} @Test void genericExceptionMaps500(){var response=handler.handleGenericException(new RuntimeException("oops"),request());assertEquals(HttpStatus.INTERNAL_SERVER_ERROR,response.getStatusCode());assertEquals("INTERNAL_SERVER_ERROR",response.getBody().code());} }
